WITH cleaned AS (SELECT id, store_id, product_id, sale_date, units, revenue, revenue * units AS revenue_per_unit FROM store_sales WHERE product_id IN (2, 8)) SELECT d.region, d.city, COUNT(*) AS num_rows, MAX(a.revenue) AS max_revenue, MAX(a.units) AS max_units, GROUPING_ID() AS level_id FROM cleaned a LEFT JOIN stores d ON a.store_id = d.id GROUP BY GROUPING SETS ((d.region, d.city), (d.region)) ORDER BY city NULLS LAST
